// @fastify/under-pressure 运行时支持 per-route `config.pressureHandler`(index.js 的
// onRequest 取 `req.routeOptions.config.pressureHandler` 优先于全局 pressureHandler),
// 但其 9.1.0 的 types/index.d.ts 只扩了 FastifyInstance(memoryUsage/isUnderPressure),
// 没扩 FastifyContextConfig —— 而 Fastify 5.12.7 的 FastifyContextConfig 是空接口
// (`types/context.d.ts`),于是路由写 `config: { pressureHandler }` 会撞 TS2353 多余属性。
// 这里按插件真实签名补齐声明;返回 undefined/null ⇒ 插件走 next() 放行(见 handlePressure),
// 因此处理器声明为 void 返回即可覆盖该分支。
import type { FastifyReply, FastifyRequest } from 'fastify'

declare module 'fastify' {
  interface FastifyContextConfig {
    /** 每路由覆盖全局压力处置;实现语义见 @fastify/under-pressure 的 handlePressure。 */
    pressureHandler?: (
      request: FastifyRequest,
      reply: FastifyReply,
      type: string,
      value: number | undefined,
    ) => Promise<void> | void
  }
}
